* Create government fiscal quarter;
data wb.contracts_gvkey_viol2; set wb.contracts_gvkey_viol2;
m = month(signed_date);
y = year(signed_date);
if m ge 10 and m le 12 then yq = cats(y+1,1);
if m ge 1 and m le 3 then  yq = cats(y,2);
if m ge 4 and m le 6 then  yq = cats(y,3);
if m ge 7 and m le 9 then  yq = cats(y,4);
yq2=yq*1;run;
